sys_script_include.script:
var FeedbackUtilsClient = Class.create();
FeedbackUtilsClient.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getFeedbackDetailsById: function() {
        var feedbackId = this.getParameter('sysparm_feedback_id');
        var gr = new GlideRecord('x_1790227_event_ma_feedback');
        gr.addQuery('number', feedbackId);
        gr.query();

        var result = [];
        while (gr.next()) {
            result.push(
                'Event: ' + gr.getDisplayValue('u_event_id') +
                ', Rating: ' + gr.getValue('u_rating') +
                ', Comments: ' + gr.getValue('u_comments')
            );
        }
        return result.length ? result.join('\n') : 'Feedback not found';
    },

    isFeedbackPositive: function() {
        var feedbackId = this.getParameter('sysparm_feedback_id');
        var gr = new GlideRecord('x_1790227_event_ma_feedback');
        gr.addQuery('number', feedbackId);
        gr.query();

        while (gr.next()) {
            var rating = gr.getValue('u_rating').toLowerCase();
            if (rating === 'excellent' || rating === 'good') {
                return 'Feedback is Positive';
            }
        }
        return 'Feedback is Negative';
    },

    getFeedbackByEventId: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('x_1790227_event_ma_feedback');
        gr.addQuery('u_event_id.number', eventId);
        gr.query();

        var result = [];
        while (gr.next()) {
            result.push(
                gr.getValue('u_rating') + ': ' + gr.getValue('u_comments')
            );
        }
        return result.length ? result.join('\n') : 'No feedback found';
    },

    type: 'FeedbackUtilsClient'
});
